import { PlatformCard } from "@/components/ui/PlatformCard";
import { useRouter } from "next/navigation";
import { Button } from "react-bootstrap";

export default function NewOrderPage() {
  const router = useRouter();
  return (
    <div>
      <div className="mb-3">
        <div className="d-flex align-items-center justify-content-between">
          <div>
            <h1 className="h5 fw-semibold mb-1">Επιλογή πλατφόρμας</h1>
            <p className="text-secondary small mb-0">
              Διάλεξε ροή εργασίας για να ξεκινήσεις.
            </p>
          </div>
        </div>
      </div>

      <PlatformCard
        title="ΕΟΠΥΥ"
        description="Ανέβασε παραπεμπτικό/γνωμάτευση και μετά συμπλήρωσε την ίδια φόρμα."
        href="/orders/new/eoppy"
        icon="bi-cloud-upload"
      />

      <PlatformCard
        title="ΕΚΤΟΣ ΕΟΠΥΥ"
        description="Συμπλήρωσε στοιχεία ασθενή/παραλήπτη/ιατρού για νέα παραγγελία."
        href="/orders/new/non-eoppy"
        icon="bi-ui-checks"
      />
      <div className="app-actionbar">
        <div className="d-flex gap-2">
          <Button variant="outline-secondary" onClick={() => router.push("/orders")} className="action-btn flex-fill">
            Άκυρο
          </Button>

          <Button variant="primary" className="action-btn flex-fill">
            Συνέχεια
          </Button>
        </div>
      </div>
    </div>
  );
}
